// CountryAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func CountryAuditing(policy CountryAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Country]()
		if err != nil {
			return err
		}
		return RegisterCountryObserver(registrar, pool, NewCountryObserver(name), func(resolver foundation.Resolver) (func() CountryHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() CountryHooks {
				write := func(ctx context.Context, tx *database.Tx, changes CountryChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return CountryHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
